package ui;

import model.Notice;import model.User;import service.NoticeService;import javax.swing.*;import javax.swing.border.EmptyBorder;import java.awt.*;

public class EditNoticeFrame extends JFrame {
    private final NoticeManagementFrame managementFrame;private final Notice notice;private final User currentUser;private final NoticeService noticeService=new NoticeService();
    private JTextField titleField,categoryField,departmentField;private JTextArea descriptionArea;private JComboBox<String> priorityBox,statusBox;
    public EditNoticeFrame(NoticeManagementFrame frame,Notice notice,User user){managementFrame=frame;this.notice=notice;currentUser=user;UITheme.styleFrame(this,"Edit Notice",720,610);setDefaultCloseOperation(JFrame.DISPOSE_ON_CLOSE);createUI();loadNoticeData();setVisible(true);}
    private void createUI(){JPanel root=new JPanel(new BorderLayout(0,15));root.setBackground(UITheme.BG);root.setBorder(BorderFactory.createEmptyBorder(22,28,22,28));JPanel head=new JPanel();head.setOpaque(false);head.setLayout(new BoxLayout(head,BoxLayout.Y_AXIS));head.add(UITheme.title("Edit Notice",24));head.add(Box.createVerticalStrut(5));head.add(UITheme.muted("Update the information and save your changes."));root.add(head,BorderLayout.NORTH);
        JPanel form=UITheme.card();form.setLayout(new GridBagLayout());GridBagConstraints c=new GridBagConstraints();c.insets=new Insets(7,8,7,8);c.fill=GridBagConstraints.HORIZONTAL;c.weightx=1;
        titleField=new JTextField();UITheme.styleField(titleField);descriptionArea=new JTextArea(5,30);descriptionArea.setLineWrap(true);descriptionArea.setWrapStyleWord(true);descriptionArea.setFont(UITheme.font(13,Font.PLAIN));descriptionArea.setBorder(new EmptyBorder(9,10,9,10));categoryField=new JTextField();departmentField=new JTextField();UITheme.styleField(categoryField);UITheme.styleField(departmentField);priorityBox=new JComboBox<>(new String[]{"LOW","MEDIUM","HIGH"});statusBox=new JComboBox<>(new String[]{"DRAFT","SUBMITTED","APPROVED","REJECTED","PUBLISHED","EXPIRED"});UITheme.styleCombo(priorityBox);UITheme.styleCombo(statusBox);
        addRow(form,c,0,"Notice Title",titleField);addRow(form,c,1,"Description",new JScrollPane(descriptionArea));addRow(form,c,2,"Category ID",categoryField);addRow(form,c,3,"Department ID",departmentField);addRow(form,c,4,"Priority",priorityBox);addRow(form,c,5,"Status",statusBox);root.add(form,BorderLayout.CENTER);
        JPanel buttons=new JPanel(new FlowLayout(FlowLayout.RIGHT));buttons.setOpaque(false);JButton cancel=UITheme.button("Cancel",false),update=UITheme.button("Update Notice",true);cancel.addActionListener(e->dispose());update.addActionListener(e->updateNotice());buttons.add(cancel);buttons.add(update);root.add(buttons,BorderLayout.SOUTH);setContentPane(root);}
    private void addRow(JPanel p,GridBagConstraints c,int r,String label,JComponent comp){c.gridy=r;c.gridx=0;c.weightx=0;p.add(UITheme.muted(label),c);c.gridx=1;c.weightx=1;comp.setPreferredSize(new Dimension(400,42));p.add(comp,c);}
    private void loadNoticeData(){titleField.setText(notice.getTitle());descriptionArea.setText(notice.getDescription());categoryField.setText(String.valueOf(notice.getCategoryId()));departmentField.setText(notice.getDepartmentId()==null?"":String.valueOf(notice.getDepartmentId()));priorityBox.setSelectedItem(notice.getPriority());statusBox.setSelectedItem(notice.getStatus());}
    private void updateNotice(){String title=titleField.getText().trim(),description=descriptionArea.getText().trim();if(title.isEmpty()||description.isEmpty()){JOptionPane.showMessageDialog(this,"Title and description are required.","Validation Error",JOptionPane.ERROR_MESSAGE);return;}try{int cat=Integer.parseInt(categoryField.getText().trim());String dep=departmentField.getText().trim();Integer depId=dep.isEmpty()?null:Integer.parseInt(dep);notice.setTitle(title);notice.setDescription(description);notice.setCategoryId(cat);notice.setDepartmentId(depId);notice.setPriority((String)priorityBox.getSelectedItem());notice.setStatus((String)statusBox.getSelectedItem());boolean ok=currentUser.getRole()==1?noticeService.updateNotice(notice):noticeService.updateNotice(notice,currentUser.getUserId());JOptionPane.showMessageDialog(this,ok?"Notice updated successfully!":"Failed to update notice.",ok?"Success":"Database Error",ok?JOptionPane.INFORMATION_MESSAGE:JOptionPane.ERROR_MESSAGE);if(ok){managementFrame.loadNotices();dispose();}}catch(NumberFormatException e){JOptionPane.showMessageDialog(this,"Category ID and Department ID must be numbers.","Input Error",JOptionPane.ERROR_MESSAGE);}}
}
